-- A SNAPSHOT written for a person when the sheet's today changed: the day being left and their
-- due-total as it stood on it (n/a when none), oldest first.
CREATE TABLE person_snapshot (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    snapshot_day DATE NOT NULL,
    due_total VARCHAR(40) NOT NULL
);
CREATE INDEX person_snapshot_sheet ON person_snapshot(sheet_id, person_id, id);
package net.officefloor.hq.app.rollup;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Records, before the sheet's today changes, a SNAPSHOT line per person in list order with their
 * due-total as it stood on the day being left, and keeps each on the person as a snapshot line.
 */
public class AuditSnapshot {
    public void audit(@Val Sheet sheet, @Val Rollup before, HttpServletRequest request, Audit audit,
            PersonRepository people) {
        String head = " sheet=" + sheet.id() + " by=" + Audit.user(request);
        before.people().forEach((id, figures) -> {
            people.addSnapshot(sheet.id(), id, sheet.today(), figures.dueTotal());
            audit.record("SNAPSHOT" + head + " name=" + figures.name() + " due-total=" + figures.dueTotal());
        });
    }
}
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import type { Person } from '../people/people';

function SnapshotsHead() {
  return <th>Snapshots</th>;
}

// A person's snapshot lines: one per SNAPSHOT written for them when the sheet's today changed,
// oldest first, each as '<the day being left> <due-total>'.
function PersonSnapshots({ person }: { sheetId: string; person: Person }) {
  return (
    <td>
      {person.snapshots.map((line, i) => (
        <div key={i} data-testid="person-snapshot-line">
          {line}
        </div>
      ))}
    </td>
  );
}

export const contributions = [
  PersonHead.fill({ order: 67, Component: SnapshotsHead }),
  PersonRow.fill({ order: 67, Component: PersonSnapshots }),
];
