  id: string;
  name: string;
  grade: Grade;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: Hold[];
  patronIds: string[];
  patronShares: string[];
  grades: GradeFrom[];
  terms: string;
  contact: string;
  tags: string[];
  aliases: string[];
  clashing: boolean;
  origin: string;
  retirements: string[];
  snapshots: string[];
  statementLines: string[];
  flag: string;
  approver: string;
};

/**
 * A hold on a person: from a date to a date (yyyy-MM-dd; `to` '' when open-ended), both inclusive.
