import { SheetBody } from '../../slots/defs/sheetBody';
import { isReviewLate, useClaims } from '../claims/claims';
import type { ClaimStatus } from '../claims/claims';
import { GRADES, liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { diffDue, personDueTotal, sumDue, useRates } from '../rates/rates';
import { useCap, useFloor, useLate, useReviewSla } from '../access/access';
import { useSheetToday } from '../sheet/sheet';
import { periodDueTotal, usePeriods } from '../periods/periods';
import { isActive } from '../active/active';
import { useVoidReasons } from '../voidreasons/voidReasons';

// Every status the summary counts.
const STATUSES: ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'];

// The sheet's summary, worked from the same figures as the lists: per grade, the people on it today
// (retired people left out), their due-totals added up and how many of them are active; per
// period, its due-total and its change from the period before it by from-date (none for the
// earliest); per status, how many claims have it; per void reason on the list, how many
// VOID claims were voided with it; and how many claims are late for review.
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const reviewSla = useReviewSla(sheetId);
  const voidReasons = useVoidReasons(sheetId).data ?? [];

  const active = people.filter((p) => !p.retired);
  const claimsOf = (p: Person) => claims.filter((c) => c.personId === p.id);
  const dueOf = (p: Person) => personDueTotal(rates, p.grades, today, claimsOf(p), liveHolds(p, today), floor, late, cap);

  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{sumDue(onGrade.map(dueOf))}</td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => isActive(claimsOf(p), liveHolds(p, today), today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => {
            const due = periodDueTotal(p, people, claims, rates, floor, late);
            const previous = [...periods].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0)).filter((q) => q.from < p.from).pop();
            return (
              <tr key={p.name}>
                <td>{p.name}</td>
                <td data-testid={`summary-period-${p.name}-due-total`}>{due}</td>
                <td data-testid={`summary-period-${p.name}-change`}>
                  {previous ? diffDue(due, periodDueTotal(previous, people, claims, rates, floor, late)) : ''}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
          <tr>
            <td>REVIEW late</td>
            <td data-testid="summary-review-late-count">{claims.filter((c) => isReviewLate(c, today, reviewSla)).length}</td>
          </tr>
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map(({ reason }) => (
            <tr key={reason}>
              <td>{reason}</td>
              <td data-testid={`summary-void-${reason}-count`}>
                {claims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 30, Component: Summary });
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation } from '@tanstack/react-query';
import { SheetBody } from '../../slots/defs/sheetBody';
import { searchTree } from './treeSearch';
import type { Found } from './treeSearch';

// The tree search: a box and a button list everyone, over this sheet and every other sheet of its
// tree, whose name or an alias holds the typed text (case ignored; blank: everyone), one line each
// as <sheet id> <name> <due-total>, this sheet's people first in list order, then the other sheets'
// by sheet id. Always read fresh; the count is cleared while it runs.
function TreeSearch({ sheetId }: { sheetId: string }) {
  const [text, setText] = useState('');
  const [found, setFound] = useState<Found[] | null>(null);
  const [error, setError] = useState('');

  const search = useMutation({
    mutationFn: (t: string) => searchTree(sheetId, t),
    onSuccess: setFound,
    onError: () => setError('The search could not be run.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setFound(null);
    setError('');
    search.mutate(text.trim());
  };

  return (
    <section data-testid="tree-search">
      <form onSubmit={submit}>
        <label>
          Search the tree{' '}
          <input
            data-testid="search-name"
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="search" disabled={search.isPending}>
          Search
        </button>
        {found !== null && (
          <>
            {' '}Found <span data-testid="search-count">{found.length}</span>
            <ul>
              {found.map((f, i) => (
                <li key={i} data-testid="search-line">
                  {f.sheetId} {f.name} {f.dueTotal}
                </li>
              ))}
            </ul>
          </>
        )}
        {error && (
          <p role="alert" data-testid="search-error">
            {error}
          </p>
        )}
      </form>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 2.5, Component: TreeSearch });

